from pathlib import Path
import importlib.util,json,hashlib,sys,time,re

EV=Path(__file__).parent
name,label=sys.argv[1:]
assert re.fullmatch(r'windows-native-[a-z-]+\.json',name) and re.fullmatch(r'[a-z-]+',label)
r=json.loads((EV/name).read_text());run=next(x['result'] for x in r['phases'] if x['name']=='execute')
assert run['physicalExit'] and not r['newPrivateTestRoots']
spec=importlib.util.spec_from_file_location('fcprobe',Path('/workspace/共享/Eliora/未来教室计划/scripts/windows-probe.py'));m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
remote=m.Remote('elior@192.168.10.212',Path('/config/.local/share/future-classroom-test-access/win11-192.168.10.212'))
owner='future-classroom-owned-r63-native/v1:'+r['nonce']
files=[{'name':Path(r['exe']).name,'sha256':r['exeSha256']},{'name':'.owner','sha256':hashlib.sha256(owner.encode()).hexdigest()}]+[{k:f[k] for k in ['name','sha256']} for f in r['originals']]
ps=r'''$root=__ROOT__;if([IO.File]::ReadAllText((Join-Path $root '.owner')) -cne '__OWNER__'){throw 'Owner mismatch'};$p=Get-Process -Id __PID__ -ErrorAction SilentlyContinue;if($p){try{if($p.StartTime.ToUniversalTime().ToFileTimeUtc() -eq __CREATED__){throw 'Original still present'}}finally{$p.Dispose()}};$expected='__FILES__'|ConvertFrom-Json;$files=@(Get-ChildItem -LiteralPath $root -Force);if($files.Count -ne @($expected).Count -or ((Get-Item -LiteralPath $root).Attributes -band [IO.FileAttributes]::ReparsePoint)){throw 'Scope differs'};foreach($f in $files){$e=@($expected|Where-Object{$_.name -ceq $f.Name});if($e.Count -ne 1 -or $f.PSIsContainer -or ($f.Attributes -band [IO.FileAttributes]::ReparsePoint) -or (Get-FileHash -LiteralPath $f.FullName -Algorithm SHA256).Hash.ToLowerInvariant() -cne $e[0].sha256){throw 'Exact file differs'}};foreach($f in $files){[IO.File]::Delete($f.FullName)};[IO.Directory]::Delete($root,$false);@{status='PASS_EXACT_TRANSPORT_CLEANUP';directoryAbsent=(-not(Test-Path -LiteralPath $root));privateTestRoots=@(Get-ChildItem -LiteralPath ([Environment]::GetFolderPath('LocalApplicationData')) -Directory -Filter 'FutureClassroom-Installer-Test-*'|ForEach-Object{$_.Name});originalObservedExitCode=__EXIT__;deletedFiles=$expected;sshd=(Get-Service sshd).Status.ToString();scope='Original evidence collected locally; only this exact copied EXE/logs/owner removed'}|ConvertTo-Json -Depth 7 -Compress'''.replace('__ROOT__',m.ps_literal(r['remoteRoot'])).replace('__OWNER__',owner).replace('__PID__',str(run['pid'])).replace('__CREATED__',str(run['creationFileTime'])).replace('__EXIT__',str(run['exitCode'])).replace('__FILES__',json.dumps(files,separators=(',',':')))
p=EV/label;p.with_suffix('.input.ps1').open('x').write(ps+'\n');t=time.monotonic();raw=remote.powershell(ps);p.with_suffix('.stdout').open('x').write(raw+'\n');v=json.loads(raw);result={'status':v['status'],'elapsedSeconds':time.monotonic()-t,'stdoutSha256':hashlib.sha256((raw+'\n').encode()).hexdigest(),'original':v};p.with_suffix('.json').open('x').write(json.dumps(result,indent=2)+'\n');print(json.dumps({'status':v['status'],'directoryAbsent':v['directoryAbsent'],'privateTestRoots':v['privateTestRoots'],'originalObservedExitCode':v['originalObservedExitCode']}));assert v['directoryAbsent'] and not v['privateTestRoots']
